// Settings sections preserve the existing forms and their event handlers.
let apiTokenEpoch=0,apiCatalog=[],apiTokensLoading=false;
const settingsRoot=$('#settings');
const settingsGroups=[['operation','Operação'],['robots','Robôs e monitoramento'],['commissions','Comissões'],['integrations','Integrações'],['account','Conta e diagnóstico'],['partners','Parceiros']];
const settingsNav=document.createElement('div');settingsNav.className='settings-tabs';settingsNav.setAttribute('role','tablist');settingsNav.setAttribute('aria-label','Seções das configurações');
settingsNav.innerHTML=settingsGroups.map(([id,label],i)=>`<button type="button" id="settings-tab-${id}" role="tab" aria-controls="settings-${id}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-settings-section="${id}">${label}</button>`).join('');
settingsRoot.insertBefore(settingsNav,settingsRoot.querySelector('.portal-card'));
for(const [id,label] of settingsGroups){const section=document.createElement('section');section.id='settings-'+id;section.className='settings-panel';section.setAttribute('role','tabpanel');section.setAttribute('aria-labelledby','settings-tab-'+id);section.hidden=id!=='operation';settingsRoot.appendChild(section);}
$('#settings-operation').appendChild(settingsRoot.querySelector('.portal-card'));
$('#settings-robots').appendChild(settingsRoot.querySelector('.robot-health'));$('#settings-robots').appendChild(settingsRoot.querySelector('.monitor-card'));
const commissionCard=document.createElement('div');commissionCard.className='card';commissionCard.appendChild($('#amigozSettings'));$('#settings-commissions').appendChild(commissionCard);
$('#settings-account').appendChild($('#authState').closest('.card'));
$('#settings-integrations').innerHTML=`<section class="card api-card"><div class="heading"><div><span class="section-kicker">API V1</span><h2>Conecte seus sistemas</h2><p>Crie campanhas, envie leads e acompanhe as consultas pela API.</p></div><a class="download-model" href="openapi.json" download="apoiarcred-openapi.json">↓ OpenAPI / Postman</a></div><label class="field" for="apiBase">Endereço base</label><div class="api-copy-row"><input id="apiBase" readonly><button type="button" id="copyApiBase">Copiar endereço</button></div><p class="muted">Fluxo: criar campanha pausada → adicionar leads → iniciar → acompanhar resultados.</p><div class="api-token-layout"><div><h3>Novo token</h3><form id="apiTokenForm"><label class="field" for="apiTokenName">Nome da integração</label><input id="apiTokenName" required maxlength="80" placeholder="Ex.: n8n comercial"><label class="field" for="apiTokenExpiry">Validade</label><select id="apiTokenExpiry"><option value="30">30 dias</option><option value="90" selected>90 dias</option><option value="365">1 ano</option><option value="">Sem expiração</option></select><fieldset class="api-scopes"><legend>Permissões</legend><label><input type="checkbox" id="apiScopeRead" checked> Ler campanhas e resultados</label><label><input type="checkbox" id="apiScopeCampaign"> Criar e gerenciar campanhas</label><label><input type="checkbox" id="apiScopeIndividual"> Solicitar consultas individuais</label></fieldset><button class="primary" id="createApiToken">Gerar token</button></form></div><div><h3>Tokens da sua conta</h3><p class="muted">Revogue um token para interromper novas requisições dessa integração.</p><button type="button" id="refreshApiTokens">Atualizar lista</button><div id="apiTokens"></div></div></div><div id="apiNewTokenPanel" class="api-new-token" hidden><h3>Copie e guarde seu token</h3><p>Ele aparece apenas agora. A lista mostrará somente o prefixo.</p><input id="apiNewToken" readonly type="password" autocomplete="off" aria-label="Token recém-gerado"><div class="actions"><button type="button" id="copyApiToken">Copiar token</button><button type="button" id="showApiToken">Mostrar</button><button type="button" id="dismissApiToken">Já guardei</button></div></div><p id="apiTokenStatus" role="status"></p></section><section class="card api-card"><h2>Documentação e exemplos</h2><p>Use <code>Authorization: Bearer SEU_TOKEN</code>. O token acessa somente os dados da sua conta.</p><div class="api-doc-notes"><p><strong>Escritas sem duplicação:</strong> envie <code>Idempotency-Key</code> única por operação. Em uma nova tentativa, reutilize a mesma chave e payload por até 24 horas.</p><p><strong>Fila assíncrona:</strong> a API confirma o recebimento. Acompanhe o identificador até a consulta terminar. Pausar permite concluir os CPFs já em execução.</p><p><strong>Dados:</strong> Digi+ exige nome, CPF e telefone. ConsigX exige apenas CPF e convênio. Parceiros podem enviar até 1.000 leads por requisição. Administradores não têm limite de quantidade. Cada requisição suporta até 2 MB. CPF é texto, preservando zeros à esquerda.</p><p><strong>n8n:</strong> importe o cURL de uma rota no nó HTTP Request. Configure uma credencial Header Auth com nome Authorization e valor Bearer SEU_TOKEN. Preserve a mesma chave nas retentativas.</p><p><strong>Paginação:</strong> page e page_size (1 a 100; padrão 50). Campanhas aceitam servico e paused; leads da campanha aceitam status. A busca por CPF usa POST /leads/buscar.</p><p><strong>Erros:</strong> 400 requisição, 401 token, 403 permissão, 404 não encontrado, 409 conflito, 422 validação, 429 limite (120/minuto por token e proteção de 5 requisições/s por IP, com rajada de 20), 503 indisponibilidade. Respostas incluem request_id.</p></div><label class="field" for="apiRouteSelect">Escolha a rota</label><select id="apiRouteSelect"><option>Carregando documentação…</option></select><div id="apiRouteDocs"></div><p id="apiDocsStatus" role="status"></p></section>`;
$('#apiBase').value=location.origin+'/api/v1';
function switchSettings(id){
 for(const [key] of settingsGroups){const selected=key===id;$('#settings-'+key).hidden=!selected;const button=$('#settings-tab-'+key);button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;}
 if(id==='integrations'){loadApiTokens();loadApiDocs();}if(id==='robots')tickMonitoring();
}
settingsNav.onclick=e=>{const button=e.target.closest('[data-settings-section]');if(button)switchSettings(button.dataset.settingsSection);};
settingsNav.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=[...settingsNav.querySelectorAll('button')].filter(b=>!b.hidden),i=buttons.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;switchSettings(buttons[next].dataset.settingsSection);buttons[next].focus();};
async function copyApi(text){try{await navigator.clipboard.writeText(text);toast('Copiado.');}catch{toast('Não foi possível copiar. Selecione e copie o campo.');}}
$('#copyApiBase').onclick=()=>copyApi($('#apiBase').value);
function clearNewApiToken(){$('#apiNewToken').value='';$('#apiNewToken').type='password';$('#apiNewTokenPanel').hidden=true;$('#showApiToken').textContent='Mostrar';}
function resetApiSettings(){apiTokenEpoch++;switchSettings('operation');clearNewApiToken();$('#apiTokens').innerHTML='';$('#apiTokenStatus').textContent='';$('#apiTokenName').value='';$('#apiScopeRead').checked=true;$('#apiScopeCampaign').checked=false;$('#apiScopeIndividual').checked=false;}
$('#copyApiToken').onclick=()=>copyApi($('#apiNewToken').value);$('#dismissApiToken').onclick=clearNewApiToken;
$('#showApiToken').onclick=()=>{const hidden=$('#apiNewToken').type==='password';$('#apiNewToken').type=hidden?'text':'password';$('#showApiToken').textContent=hidden?'Ocultar':'Mostrar';};
async function loadApiTokens(){
 if(!authenticated||apiTokensLoading||typeof hasIntegrationAccess==='function'&&!hasIntegrationAccess())return;apiTokensLoading=true;const epoch=authEpoch;
 try{const rows=await sbRequest('/rest/v1/rpc/manage_api_tokens',{method:'POST',body:JSON.stringify({p_action:'list',p_input:{}})});if(epoch!==authEpoch||typeof hasIntegrationAccess==='function'&&!hasIntegrationAccess())return;
 $('#apiTokens').innerHTML=rows.length?rows.map(t=>{const expired=t.expires_at&&Date.parse(t.expires_at)<=Date.now(),disabled=t.revoked_at||expired;return `<article class="api-token-row"><div><strong>${escapeHTML(t.name)}</strong><span class="pill ${disabled?'':'ok'}">${t.revoked_at?'Revogado':expired?'Expirado':'Ativo'}</span></div><code>${escapeHTML(t.prefix)}…</code><p>${escapeHTML(t.scopes.join(' · '))}</p><small>Criado: ${escapeHTML(new Date(t.created_at).toLocaleString('pt-BR'))}<br>Validade: ${t.expires_at?escapeHTML(new Date(t.expires_at).toLocaleString('pt-BR')):'Sem expiração'}<br>Último uso: ${t.last_used_at?escapeHTML(new Date(t.last_used_at).toLocaleString('pt-BR')):'Ainda não utilizado'}</small>${disabled?'':`<button type="button" class="danger" data-revoke-api="${escapeHTML(t.id)}">Revogar</button>`}</article>`;}).join(''):'<p class="muted">Nenhum token criado. Gere um para sua primeira integração.</p>';
 }catch(e){if(epoch===authEpoch)$('#apiTokenStatus').textContent='Não foi possível carregar tokens. Confira a conexão e a atualização do banco.';}
 finally{apiTokensLoading=false;}
}
$('#refreshApiTokens').onclick=loadApiTokens;
$('#apiTokenForm').onsubmit=async e=>{
 e.preventDefault();if(!$('#apiNewTokenPanel').hidden){$('#apiTokenStatus').textContent='Guarde o token atual e clique em Já guardei antes de gerar outro.';return;}
 const scopes=[];if($('#apiScopeRead').checked)scopes.push('read');if($('#apiScopeCampaign').checked)scopes.push('campanhas:write');if($('#apiScopeIndividual').checked)scopes.push('consultas:create');if(!scopes.length){$('#apiTokenStatus').textContent='Escolha ao menos uma permissão.';return;}
 const epoch=authEpoch,requestEpoch=++apiTokenEpoch;$('#createApiToken').disabled=true;$('#apiTokenStatus').textContent='Gerando token…';
 try{const days=$('#apiTokenExpiry').value;const r=await sbRequest('/rest/v1/rpc/manage_api_tokens',{method:'POST',body:JSON.stringify({p_action:'create',p_input:{name:$('#apiTokenName').value.trim(),scopes,expires_at:days?new Date(Date.now()+Number(days)*86400000).toISOString():null}})});if(epoch!==authEpoch||requestEpoch!==apiTokenEpoch||typeof hasIntegrationAccess==='function'&&!hasIntegrationAccess())return;
 $('#apiNewToken').value=r.token;$('#apiNewTokenPanel').hidden=false;$('#apiTokenStatus').textContent='Token gerado. Copie e guarde antes de sair.';await loadApiTokens();
 }catch(e){if(epoch===authEpoch)$('#apiTokenStatus').textContent=e.message;}
 finally{$('#createApiToken').disabled=false;}
};
$('#apiTokens').onclick=async e=>{const id=e.target.dataset.revokeApi;if(!id||!confirm('Revogar este token? A integração deixará de acessar a API.'))return;const epoch=authEpoch;e.target.disabled=true;
 try{await sbRequest('/rest/v1/rpc/manage_api_tokens',{method:'POST',body:JSON.stringify({p_action:'revoke',p_input:{id}})});if(epoch!==authEpoch||typeof hasIntegrationAccess==='function'&&!hasIntegrationAccess())return;clearNewApiToken();$('#apiTokenStatus').textContent='Token revogado.';await loadApiTokens();}catch(error){if(epoch===authEpoch)$('#apiTokenStatus').textContent=error.message;}finally{e.target.disabled=false;}};
async function loadApiDocs(){
 if(apiCatalog.length)return;try{const response=await fetch('api-catalog.json');if(!response.ok)throw Error();apiCatalog=await response.json();$('#apiRouteSelect').innerHTML=apiCatalog.map((r,i)=>`<option value="${i}">${escapeHTML(r.method+' '+r.path+' · '+r.summary)}</option>`).join('');renderApiRoute();}catch{$('#apiDocsStatus').textContent='Não foi possível carregar a documentação. Atualize a página.';}
}
function renderApiRoute(){
 const r=apiCatalog[Number($('#apiRouteSelect').value||0)];if(!r)return;
 let curl=`curl --request ${r.method} '${location.origin}/api/v1${r.path}' \\\n  --header 'Authorization: Bearer SEU_TOKEN'`;
 if(r.body!==null){curl+=" \\\n  --header 'Content-Type: application/json'";if(r.path!=='/leads/buscar')curl+=" \\\n  --header 'Idempotency-Key: operacao-123'";curl+=" \\\n  --data '"+JSON.stringify(r.body)+"'";}
 $('#apiRouteDocs').innerHTML=`<p><strong>${escapeHTML(r.summary)}</strong> · Permissão: <code>${escapeHTML(r.scope)}</code></p><p class="muted">Substitua {id} pelo identificador retornado. Os exemplos usam dados fictícios.</p>${r.body!==null?`<h3>Payload JSON</h3><pre>${escapeHTML(JSON.stringify(r.body,null,2))}</pre>`:''}<div class="heading"><h3>cURL / importar no n8n</h3><button type="button" id="copyApiCurl">Copiar cURL</button></div><pre>${escapeHTML(curl)}</pre><h3>Resposta ${r.status}</h3><pre>${escapeHTML(JSON.stringify(r.response,null,2))}</pre>`;
 $('#copyApiCurl').onclick=()=>copyApi(curl);
}
$('#apiRouteSelect').onchange=renderApiRoute;
